// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 timestamp, uint256 blockNum) public {
        vm.assume(value >= 0);
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(blockNum);
        vm.deal(address(this), value);
        (bool success, ) = address(c).call{value: value}("");
        if (success) {
            assertEq(value, 10 ether, "Successful call must have sent exactly 10 ether");
        }
    }
}
